class ThreatAwareSystem
  attr_reader :system_id, :threats

  def initialize(system_id, threats) = (@system_id, @threats = system_id, threats)

  def filtered(&keep)
    self.class.new(system_id, threats.select(&keep))
  end
end

rootkits = system.filtered { |t| t.type == :rootkit }
named    = system.filtered(&:known?)
top10    = system.threats.lazy.select(&:known?).map(&:name).first(10)
